@page "/apply"
@rendermode InteractiveServer
@using sv_44efeb69db8c44d1abbaf7e3c368f29a.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* Step Indicator Bar *@
    <nav class="mb-4">
        <div class="d-flex justify-content-between position-relative">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var isCompleted = stepIndex < CurrentStep;
                var isCurrent = stepIndex == CurrentStep;
                var isFuture = stepIndex > CurrentStep;
                var isClickable = isCompleted && !Submitted;

                <div class="text-center flex-fill" style="z-index: 1;">
                    <button type="button"
                            class="btn rounded-circle d-inline-flex align-items-center justify-content-center @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary") @(!isClickable ? "" : "shadow-sm")"
                            style="width: 36px; height: 36px; font-size: 0.85rem;"
                            disabled="@(!isClickable)"
                            @onclick="() => GoToStep(stepIndex)">
                        @if (isCompleted)
                        {
                            <span>✓</span>
                        }
                        else
                        {
                            <span>@(stepIndex + 1)</span>
                        }
                    </button>
                    <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold" : "")">
                        @_stepNames[stepIndex]
                    </div>
                </div>
            }
        </div>
    </nav>

    @if (Submitted)
    {
        <div class="alert alert-success text-center py-5">
            <h3>🎉 Application Submitted!</h3>
            <p class="fs-5 mt-3">Your application has been received.</p>
            <p class="fs-4 fw-bold">Application ID: @ApplicationId</p>
        </div>
    }
    else
    {
        @* Validation errors *@
        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
                    @foreach (var error in _errors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        @switch (CurrentStep)
        {
            case 0:
                <StepPersonalInfo @bind-FullName="FullName"
                                  @bind-Email="Email"
                                  @bind-Phone="Phone"
                                  @bind-Address="Address" />
                break;
            case 1:
                <StepWorkHistory WorkEntries="WorkEntries" />
                break;
            case 2:
                <StepReferences References="References" />
                break;
            case 3:
                <StepCoverLetter @bind-CoverLetter="CoverLetter" MaxLength="2000" />
                break;
            case 4:
                <StepReview FullName="@FullName" Email="@Email" Phone="@Phone" Address="@Address"
                            WorkEntries="WorkEntries" References="References" CoverLetter="@CoverLetter"
                            OnEditSection="GoToStep" />
                break;
        }

        @* Navigation Buttons *@
        <div class="d-flex justify-content-between mt-4">
            <div>
                @if (CurrentStep > 0)
                {
                    <button type="button" class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@IsProcessing">
                        ← Back
                    </button>
                }
            </div>
            <div>
                @if (CurrentStep < _stepNames.Length - 1)
                {
                    <button type="button" class="btn btn-primary" @onclick="NextStep" disabled="@IsProcessing">
                        @if (IsProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Next →
                    </button>
                }
                else
                {
                    <button type="button" class="btn btn-success" @onclick="SubmitApplication" disabled="@IsProcessing">
                        @if (IsProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                            <span>Submitting…</span>
                        }
                        else
                        {
                            <span>Submit Application</span>
                        }
                    </button>
                }
            </div>
        </div>
    }
</div>

@code {
    private static readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private bool Submitted { get; set; }
    private bool IsProcessing { get; set; }
    private int ApplicationId { get; set; }
    private List<string> _errors = new();

    // Step 1
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string CoverLetter { get; set; } = "";

    private void GoToStep(int step)
    {
        if (step < CurrentStep && !Submitted)
        {
            _errors.Clear();
            CurrentStep = step;
        }
    }

    private void PreviousStep()
    {
        if (CurrentStep > 0)
        {
            _errors.Clear();
            CurrentStep--;
        }
    }

    private async Task NextStep()
    {
        _errors.Clear();
        if (!await ValidateCurrentStep()) return;
        CurrentStep++;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        IsProcessing = true;
        try
        {
            switch (CurrentStep)
            {
                case 0:
                    if (string.IsNullOrWhiteSpace(FullName)) _errors.Add("Full name is required.");
                    if (string.IsNullOrWhiteSpace(Email)) _errors.Add("Email is required.");
                    if (string.IsNullOrWhiteSpace(Phone)) _errors.Add("Phone is required.");
                    if (string.IsNullOrWhiteSpace(Address)) _errors.Add("Address is required.");
                    if (_errors.Count == 0)
                    {
                        var emailValid = await ApplicationService.ValidateEmailAsync(Email);
                        if (!emailValid) _errors.Add("Please enter a valid email address.");
                    }
                    break;
                case 1:
                    for (int i = 0; i < WorkEntries.Count; i++)
                    {
                        var e = WorkEntries[i];
                        var label = $"Position {i + 1}";
                        if (string.IsNullOrWhiteSpace(e.Company)) _errors.Add($"{label}: Company name is required.");
                        if (string.IsNullOrWhiteSpace(e.Title)) _errors.Add($"{label}: Job title is required.");
                        if (e.StartDate == default) _errors.Add($"{label}: Start date is required.");
                        if (!e.IsCurrent && e.EndDate == default) _errors.Add($"{label}: End date is required (or mark as current position).");
                    }
                    break;
                case 2:
                    for (int i = 0; i < References.Count; i++)
                    {
                        var r = References[i];
                        var label = $"Reference {i + 1}";
                        if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"{label}: Name is required.");
                        if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"{label}: Relationship is required.");
                        if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"{label}: Email is required.");
                        if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"{label}: Phone is required.");
                    }
                    break;
                case 3:
                    if (string.IsNullOrWhiteSpace(CoverLetter)) _errors.Add("Cover letter is required.");
                    if (CoverLetter.Length > 2000) _errors.Add("Cover letter must be 2000 characters or fewer.");
                    break;
            }
            return _errors.Count == 0;
        }
        finally
        {
            IsProcessing = false;
        }
    }

    private async Task SubmitApplication()
    {
        IsProcessing = true;
        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(
                WorkEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()
            );
            var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, refs, CoverLetter);

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            Submitted = true;
        }
        finally
        {
            IsProcessing = false;
        }
    }

    // Mutable models for form binding
    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@using static sv_44efeb69db8c44d1abbaf7e3c368f29a.Components.Pages.Apply.Apply

<h4>Work History</h4>

@for (int i = 0; i < WorkEntries.Count; i++)
{
    var index = i;
    var entry = WorkEntries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (WorkEntries.Count > 1)
                {
                    <button type="button" class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>
            <div class="row">
                <div class="col-md-6 mb-3">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="entry.Company" @bind:event="oninput" />
                </div>
                <div class="col-md-6 mb-3">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="entry.Title" @bind:event="oninput" />
                </div>
            </div>
            <div class="row">
                <div class="col-md-4 mb-3">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" @bind="entry.StartDate" />
                </div>
                <div class="col-md-4 mb-3">
                    <label class="form-label">End Date @(entry.IsCurrent ? "" : "*")</label>
                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                </div>
                <div class="col-md-4 mb-3 d-flex align-items-end">
                    <div class="form-check">
                        <input type="checkbox" class="form-check-input" id="current-@index" @bind="entry.IsCurrent" />
                        <label class="form-check-label" for="current-@index">Current position</label>
                    </div>
                </div>
            </div>
            <div class="mb-2">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" @bind="entry.Description" @bind:event="oninput"></textarea>
            </div>
        </div>
    </div>
}

<button type="button" class="btn btn-outline-primary btn-sm" @onclick="AddEntry">
    + Add Another Position
</button>

@code {
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = new();

    private void AddEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }
}

@using static sv_44efeb69db8c44d1abbaf7e3c368f29a.Components.Pages.Apply.Apply

<h4>References</h4>
<p class="text-muted">Please provide 2–3 professional references.</p>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    var reference = References[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Reference @(index + 1)</h6>
