                        var r = References[i];
                        var label = $"Reference {i + 1}";
                        if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"{label}: Name is required.");
                        if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"{label}: Relationship is required.");
                        if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"{label}: Email is required.");
                        if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"{label}: Phone is required.");
                    }
                    break;
                case 3:
                    if (string.IsNullOrWhiteSpace(CoverLetter)) _errors.Add("Cover letter is required.");
                    if (CoverLetter.Length > 2000) _errors.Add("Cover letter must be 2000 characters or fewer.");
                    break;
            }
            return _errors.Count == 0;
        }
        finally
        {
            IsProcessing = false;
        }
    }

    private async Task SubmitApplication()
    {
        IsProcessing = true;
        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(
                WorkEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()
            );
            var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, refs, CoverLetter);

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            Submitted = true;
        }
        finally
        {
            IsProcessing = false;
        }
    }

    // Mutable models for form binding
    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
